        const yr = el('text', { x: small && i === 0 ? cx + band : cx, y: H - M.b + 33, 'text-anchor': 'middle', class: 'year' }, chart);""",
"""      // Year markers sit under the first labelled month of each year
      const yearAt = small ? (i === 1 || i === 3) : (i === 0 || d.m === 'Jan');
