input.command:
cd "$PWD" && D=$TMPDIR/tmp.ILUwtTzCYT; cat > $D/test.html <<EOF
<html><body><pre id="out"></pre><iframe id="f" src="file://$PWD/index.html" style="width:390px;height:900px"></iframe>
<script>
const f=document.getElementById('f');const out=[];
window.onerror=(m)=>out.push('ERR '+m);
f.onload=()=>{setTimeout(()=>{try{
 const d=f.contentDocument,w=f.contentWindow;
 w.addEventListener('error',e=>out.push('IFRAME ERR '+e.message));
 const names=()=>[...d.querySelectorAll('#cafeBody .cafe-name')].map(n=>n.textContent).join(',');
 out.push('default: '+names());
 const btn=k=>d.querySelector('#cafeTable th[data-key='+k+'] button');
 btn('change').click(); out.push('change desc: '+names()+' aria='+d.querySelector('#cafeTable th[data-key=change]').getAttribute('aria-sort'));
 btn('change').click(); out.push('change asc: '+names());
 btn('name').click(); out.push('name asc: '+names());
 d.querySelector('.segmented [data-mode=online]').click();
 out.push('online bars: '+d.querySelectorAll('#revChart rect[fill]').length+' summary='+d.querySelector('#chartSummary').textContent.trim());
 const svg=d.getElementById('revChart'); svg.focus();
 svg.dispatchEvent(new w.KeyboardEvent('keydown',{key:'ArrowLeft',bubbles:true}));
 out.push('tooltip: '+d.getElementById('tooltip').textContent+' on='+d.getElementById('tooltip').classList.contains('on'));
 out.push('live: '+d.getElementById('chartLive').textContent);
 const q=d.getElementById('q'); q.value='online'; q.dispatchEvent(new w.Event('input'));
 setTimeout(()=>{
  out.push('search: '+d.getElementById('searchStatus').textContent);
  d.getElementById('menuBtn').click();
  out.push('drawer open: '+d.getElementById('sidebar').classList.contains('open')+' expanded='+d.getElementById('menuBtn').getAttribute('aria-expanded'));
  out.push('scrollW '+d.documentElement.scrollWidth+' clientW '+d.documentElement.clientWidth);
  document.getElementById('out').textContent=out.join('\n');
 },400);
}catch(e){out.push('EXC '+e);document.getElementById('out').textContent=out.join('\n');}},800)};
</script></body></html>
EOF
"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" --headless=new --disable-gpu --allow-file-access-from-files --window-size=800,1000 --virtual-time-budget=5000 --dump-dom "file://$D/test.html" 2>/dev/null | sed -n '/<pre id="out">/,/<\/pre>/p'

